fyPrescriptionDecision" name="decision"><option value="start">Start review</option><option value="approve">Approve</option><option value="reject">Reject</option><option value="clarify">Request clarification</option></select><textarea class="form-control form-control-sm mb-2" name="reason" placeholder="Reason when required" rows="2"></textarea><div class="custom-control custom-checkbox mb-3"><input class="custom-control-input" type="checkbox" id="shopifyPrescriptionConfirmation" name="confirmation" value="1"><label class="custom-control-label" for="shopifyPrescriptionConfirmation">I confirm this review decision</label></div><button class="btn btn-sm btn-primary btn-block" type="submit">Save prescription review</button></form><?php endif; ?><?php else: ?><p class="text-muted mb-0">No prescription document is linked to this order.</p><?php endif; ?></div></section><?php if ($canManage): ?><section class="pharmacy-content-card mb-4"><div class="card-header"><h2 class="h6 mb-0">Process order</h2></div><div class="card-body"><form class="shopify-order-action-form mb-2" method="post" action="<?= $actionUrl ?>"><?= csrf_field() ?><input type="hidden" name="action" value="retry_validation"><button class="btn btn-primary btn-block" type="submit">Retry validation / import</button></form><form class="shopify-order-action-form mb-2" method="post" action="<?= $actionUrl ?>"><?= csrf_field() ?><input type="hidden" name="action" value="mark_ready"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Reason (optional)"><button class="btn btn-outline-primary btn-block" type="submit">Mark ready to import</button></form><form class="shopify-order-action-form mb-2" method="post" action="<?= $actionUrl ?>"><?= csrf_field() ?><input type="hidden" name="action" value="quarantine"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Quarantine reason" required><button class="btn btn-outline-warning btn-block" type="submit">Quarantine order</butt